 let raw=storage.getItem(KEY);storage.probe();if(!native){saveStatus=storage.persistent?'Browser storage available':'Temporary mode — export backup';saveProblem=storage.persistent?'':storage.reason;}if(raw)data=validateState(JSON.parse(raw));
